/** Raised when a parent placement would loop the tree or sit too deep. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or its sub-issues.`
        : `Issue ${issueId} would sit too deep in the sub-issue tree.`,
    );
    this.name = "IssueHierarchyError";
  }
}
