function isClosed(status: Issue["status"]): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

type TreeNode = Awaited<ReturnType<typeof issueRepo.listTreeNodes>>[number];

function childrenIndex(nodes: readonly TreeNode[]): Map<string, string[]> {
  const index = new Map<string, string[]>();
  for (const n of nodes) {
    if (n.parentId === null) continue;
    const list = index.get(n.parentId) ?? [];
    list.push(n.id);
    index.set(n.parentId, list);
  }
  return index;
}

/** Every id below `id` at any depth (cycle-safe), archived ones included. */
function descendantIds(nodes: readonly TreeNode[], id: string): string[] {
  const index = childrenIndex(nodes);
  const seen = new Set<string>([id]);
  const out: string[] = [];
  const stack = [id];
  while (stack.length > 0) {
    for (const child of index.get(stack.pop() as string) ?? []) {
      if (seen.has(child)) continue;
      seen.add(child);
      out.push(child);
      stack.push(child);
    }
  }
  return out;
}

function levelOf(nodes: readonly TreeNode[], id: string): number {
  const byId = new Map(nodes.map((n) => [n.id as string, n]));
  let level = 0;
  let cur = byId.get(id);
  const seen = new Set<string>();
  while (cur && cur.parentId !== null && !seen.has(cur.id)) {
    seen.add(cur.id);
    level += 1;
    cur = byId.get(cur.parentId);
  }
  return level;
}

/** Height of the subtree under `id`: 0 for a leaf. */
function heightOf(nodes: readonly TreeNode[], id: string): number {
  const index = childrenIndex(nodes);
  let max = 0;
  const seen = new Set<string>([id]);
  let frontier = [id];
  while (frontier.length > 0) {
    const next: string[] = [];
    for (const f of frontier) {
      for (const c of index.get(f) ?? []) {
        if (seen.has(c)) continue;
        seen.add(c);
        next.push(c);
      }
    }
    if (next.length > 0) max += 1;
    frontier = next;
  }
  return max;
}

function liveBelow(nodes: readonly TreeNode[], id: string): TreeNode[] {
  const ids = new Set(descendantIds(nodes, id));
  return nodes.filter((n) => ids.has(n.id) && n.archivedAt === null);
}

/** Tells the parent's assignee once its last open sub-issue has closed. */
async function notifyIfCompleted(
  actor: Actor,
  orgId: OrgId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }
  const nodes = await issueRepo.listTreeNodes(orgId, parent.projectId);
  const below = liveBelow(nodes, parent.id);
  if (below.length === 0 || below.some((n) => !isClosed(n.status))) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues completed",
    body: `Every sub-issue of issue ${parent.id} is closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}

/**
 * Places an issue under a parent of its own project, moves it, or makes it a
 * root again (`parentId: null`). Its sub-issues move with it.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const nodes = await issueRepo.listTreeNodes(input.orgId, before.projectId);

  if (input.parentId !== null) {
    const parent = requireFound(
      await issueRepo.findIssueById(input.orgId, input.parentId),
      "Issue",
      input.parentId,
    );
    if (parent.projectId !== before.projectId) {
      throw new NotFoundError("Issue", input.parentId);
    }
    assertNotArchived("Issue", parent.id, parent);

    if (
      parent.id === before.id ||
      descendantIds(nodes, before.id).includes(parent.id)
    ) {
      throw new IssueHierarchyError(before.id, "cycle");
    }
    if (
      levelOf(nodes, parent.id) + 1 + heightOf(nodes, before.id) >
      MAX_SUB_ISSUE_DEPTH
    ) {
      throw new IssueHierarchyError(before.id, "too_deep");
    }
  }

  if (before.parentId === input.parentId) return before;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));
  return issueRepo.listLiveChildren(orgId, issueId);
}

export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);
