    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));
  const nodes = await issueRepo.listTreeNodes(orgId, issue.projectId);
  const below = liveBelow(nodes, issue.id);
  const closed = below.filter((n) => isClosed(n.status)).length;
  return { total: below.length, open: below.length - closed, closed };
}
