/** Every issue of the org, as plain rows, for tree walks done in memory. */
export async function listTreeNodes(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<
  readonly {
    id: IssueId;
    parentId: IssueId | null;
    status: IssueStatus;
